INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1536897-coe292', 'stk-user12308', 'COE 292', 'info', '{"desc": "TERM 221\n\nجودة المقرر بشكل عام: جيد والكورس ممتع.\n\nالمواضيع التي يغطيها المقرر: يغطي الكورس مواضيع منها Computer vision, Machine Learning, Constraints Satisfaction Problems, Goal Tress, Search, Neural Networks.\n\nالكتاب المستخدم للمقرر: لا يوجد، المستخدم هو سلايدات للقسم وهي تتحدث كل ترم تقريبا ويحصل تغيير في الترتيب حق المواضيع بسيط. مستواها جيد.\n\nالأسئلة والأمثلة المستخدمة في المقرر: المادة من ٢٢١ والى ٢٢٣ كانت خيارات بالكامل بالميد والفاينل. ما اقدر اقول الميد سهل او لا بحكم انه بترم ممكن يكون موضوع مثلا neural networks بالميد ويمكن يكون بالترم اللي بعده بالفاينل بدون الميد. ولكن عامةً الكورس بالإمكان يكون معقد اكثر من كذا ولكن الدكاترة مسهلينه. الواجبات اغلب الاوقات تكون نفس افكار الاترام الماضية والكويزات تكون بنفس افكار واجبات الترم نفسه. و الاختبارات يجيبوا فيها نفس افكار الكويزات مع كم سؤال لتمييز طلاب ال A+. فيه واجبات بترمنا كلها كانت يا تحلها لوحدك او معاك زميل واحد. اغلبها كانت واجبات بسيطة لكن تاخذ وقت وبعضها كانت coding.\n\nKFUPM ASME شغالين على ملفات تجميعات و شرح للمادة بتلقونها منشورة ان شاء الله تعالى بقروبهم", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/coe-292-introduction-to-artificial-intelligence/185049/2", "user": "user12308", "ts": 1693030969000, "tid": 185049, "pn": 2}}', 1693030969000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-idk-coe292', 'stk-idk', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98319", "n": "Dr. Talal Mousa Al-Kharobi", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE292 - T251\n\nالتحضير: من اغرب أنظمة التحضير الي مرت علي حضرنا في الترم ١٠ مرات يعني هو على حسب عدد الطلاب يحضر ومرات على المزاج\n\nطريقة الشرح: شرحه أبدا ما ناسبني الكورس يعتبر صعب ويشرحه بطريقة ما تساعدك أبدا بالفهم أو بالاختبارات عكس بعض الدكاترة مهمته يجلس على الكرسي ويقرا السلايدات ويترجمها بالعربي فشرحه سيء بالنسبة فإذا أنت بتاخذ ذا الكورس مو افضل خيار لأنه ماراح يساعدك باي شي\n\nالكويزات: سهلة وغريبة\n\nالمياجر والفاينلات: كومن وبالميد سكشنا معاه كان اقل افرج من بين ١٠ سكاشن\n\nالقريد النهائي: D هو عنده المقومات انه يصير كويس بس أتوقع لأنه قريب للتقاعد فما صار يهمه\n\nالصوت: واضح\n\nإضافات: إذا أنت ما يهمك الشرح مع أني أشوف هذا الكورس جدا صعب تفهمه من عمرك بالذات جزئية الميد فروح معاه لكن من الحين أقولك بتندم بس صراحة الدكتور كاخلاق جدا عسل لكن ما ينفع للتدريس وصراحة لو أني بدال أي شخص ما أخذ معاه الحمدلله افتكينا من ذا الكورس لان صراحة المشكلة الكبرى من الكورس مو هو لكنه يتحمل المسؤولية", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1540768-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-talal-mousa-al-kharobi/98319/4", "user": "idk", "ts": 1767254005725, "tid": 98319, "pn": 4}}]}', 1767254005725, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ria-coe292', 'stk-ria', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98324", "n": "Dr. Aiman H. El-Maleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE292\nالتحضير :ورقة تمر على الطلاب\nطريقة الشرح : من سلايدات كومن\nالكويزات : سهلة ( سهلة يمكن عشان الكورس نفسه سهل اصلا) بس نظام استقعاد\nالمياجر: مافيه بس ميد\nالفاينلات :كومن\nالقريد النهائي: +B\nالصوت: انجليزي واضح\nإضافات :الدكتور شرحه اجمل ما يكون بس عيبه بالكويزات مستقعد لازم تكتب الجواب بالطريقة اللى ابيها انا اذا ما كتبتها تاخذ صفر على السؤال او انقصك مع انه ممكن انت تكون فاهم الفكرة بس يصير الوضع حفظ", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1535701-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-aiman-h-el-maleh/98324/25", "user": "RIA", "ts": 1666942239000, "tid": 98324, "pn": 25}}]}', 1666942239000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12308-coe292', 'stk-user12308', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98324", "n": "Dr. Aiman H. El-Maleh", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE292-221\nالتحضير : ورقة تمر ومرة او ثنتين بس نادى الاسماء بنفسه. ما خصم ولا اعطى DN.\n\nطريقة الشرح : ممتاز جدا ومن الدكاترة القلائل اللي فاهمين الكورس وعارفين كيف يوصلون المعلومة. يستعمل السلايدات الموحدة وأغلب الوقت يكون هو اللي اصلا سواها بحكم انه منطلق بالمنهج.\n\nالكويزات : ما كان فيه كويزات خيارات وكانت رتن بعضها سهل وبعضها وسط مائل للصعوبة. بالنهاية كان افرجنا اقل من الافرج المطلوب ورفعنا للافرج بالنورم ٧٥٪؜ .\n\nالمياجر: ميد وكومون وكان خيارات واغلب الاسئلة هو كتبها.\n\nالفاينلات : خيارات\n\nالقريد النهائي: A++++++++++++\n\nالصوت: ضعيف شوي ولكن القاعه صغيرة\n\nإضافات : الدكتور ماشاء الله عليه قمة بالشرح والتعاون وسوا لنا قروب واتساب وكان يرد على اسألتنا باي وقت ويتفاعل معنا.\n\nكذلك منطلق لدرجة انه يلقى وقت يشرح الواجبات على السريع بالكلاس ويركز على واجبات البرمجة.\nمتعاون و اعاد تصحيح كم واجب لنا بحكم ان الكوردنيتور صفرها للبعض.\n\nمن الاخر نزل وانت مغمض واعرف انك محظوظ.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536902-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/prof-aiman-h-el-maleh/98324/26", "user": "user12308", "ts": 1693058699000, "tid": 98324, "pn": 26}}]}', 1693058699000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user12093-coe292', 'stk-user12093', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98329", "n": "Dr. Ahmad Almulhem", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 292 - Term 212\n\nالتحضير: كان يأخذ التحضير نصف المحاضرة أول كذا أسبوع وبعدها لم يعد يأخذ التحضير.\n\nطريقة الشرح: يشرح السلايدات العامة للمادة، شرحه جيّد ومفهوم ويستقبل الأسئلة بصدر رحب.\n\nالكويزات: اختبرنا 5 كويزات، وحذف أسوأ واحد(لجميع شُعَب المادة)، سهلة إلى متوسطة المستوى.\n\nالمياجر: اختبار نصفي(Midterm Exam) مشترك.\n\nالفاينلات: مشترك.\n\nالصوت: واضح.\n\nإضافات: لا شيء.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534522-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-ahmad-almulhem/98329/22", "user": "user12093", "ts": 1653981906000, "tid": 98329, "pn": 22}}]}', 1653981906000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-mohammed_mag-coe292', 'stk-mohammed_mag', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98334", "n": "Dr. Kamel Chenaoua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 292 - TERM 212 حضوري\n\nالتحضير :\nيحضر بعض الاحيان بالبلاكبورد اخر الكلاس\n\nطريقة الشرح : طريقه شرح الدكتور جدا ممتازه والكلاس ما تمل منه.\n\nالكويزات :\nكومن\n\nالمياجر: كومن\n\nالفاينلات : كومن\n\nالقريد النهائي: +B\n\nالصوت: واضح جدا\n\nإضافات : الدكتور تعامله جدا جميل ومن افضل الدكاتره اخلاق, يخليك تحضر حتى لو ماتحب الماده.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534501-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-kamel-chenaoua/98334/21", "user": "Mohammed_Mag", "ts": 1653828992000, "tid": 98334, "pn": 21}}]}', 1653828992000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-saleh_h-coe292', 'stk-saleh_h', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98334", "n": "Dr. Kamel Chenaoua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE 292 - Term 212\n\nالتحضير : بداية الترم كان يحضر من البلاك بورد لكن بعد الميد صار ما يحضر\nطريقة الشرح : ممتاز جدًا وكلاسه ممتع وما تمل منه\nالكويزات : سهلة الى متوسطة\nالمياجر: كومن وكان سهل\nالفاينلات : كومن وكان غثيث شوي\nالقريد النهائي:A\nالصوت: واضح جدًا ومفهوم\nإضافات : الدكتور حبيب وفلاوي وكلاسه رهيب لكن عيبه الوحيد انه يسوف واجد وبعض الاحيان يرصد لك قريد غلط فلازم تتابع وراه … اشوفه خيار ممتاز للكورس للي يبي دكتور ما يستقعد بالتحضير.", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1534506-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-kamel-chenaoua/98334/22", "user": "Saleh_H", "ts": 1653849949000, "tid": 98334, "pn": 22}}]}', 1653849949000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-zad-coe292', 'stk-zad', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f98334", "n": "Dr. Kamel Chenaoua", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE292- T221\n\nالتحضير : نادر جدا\nطريقة الشرح : جيد يوصل لك الفكرة ويعيد أكثر من مرة\nالكويزات : سهلة إلى متوسطة\nالمياجر: كومن\nالفاينلات : كومن\nالصوت: واضح جدًا ومفهوم\nإضافات : الدكتور حبيب جدا ومتعاون وكلاسه خفيف", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536498-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/mr-kamel-chenaoua/98334/23", "user": "ZAD", "ts": 1679077463000, "tid": 98334, "pn": 23}}]}', 1679077463000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-ahmed1-coe292', 'stk-ahmed1', 'COE 292', 'doc', '{"docs": [{"id": "stk-dr-f183289", "n": "Dr. Rashad Othman", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "COE292 - Term221\n\nالتحضير : نهاية الكلاس، التحضير مو كل يوم من فترة لفترة يصير يحضّر طريقة الشرح : شرح الدكتور ممتاز و ما عليه كلام و مرتب السلايدات للكورس بشكل افضل عشان تفهم و يعطيك امثلة زيادة عشان يوضح الكونسبت بشكل اكبر (هالكورس يحتاج دكتور شريح لان ماتيريال الفاينل صعب تفهمه من السلايدات بدون شرح)\nالكويزات : متوسطة المستوى وتجهزك للميد والفاينل، الافرج تقريبا حول ال 70%\nالمياجر: كومن\nالفاينلات : كومن\nالتقييم النهائي: A+\nالصوت: واضح\nإضافات : ما يحتاج اتكلم، الدكتور جدا متعاون من كل النواحي و شخص جدا مريح و يحاول يتساعد مع الكل ويجاوب على اسئلتهم سواء في الكلاس او خارج الكلاس (تيمز او واتس).", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1536047-coe292", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/rashad-othman/183289/9", "user": "Ahmed1", "ts": 1671672694000, "tid": 183289, "pn": 9}}]}', 1671672694000, 1794774614, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
